package com.hms.social;
import com.hms.tenancy.*; import java.time.OffsetDateTime; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/social/connections") public class SocialSyncController {private final TenantRepository tenants;private final SocialConnectionRepository connections;public SocialSyncController(TenantRepository t,SocialConnectionRepository c){tenants=t;connections=c;} @PostMapping("/{connectionId}/sync") public SocialConnection sync(@PathVariable String tenantSlug,@PathVariable UUID connectionId){UUID tenant=tenants.findBySlug(tenantSlug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug));SocialConnection c=connections.findById(connectionId).filter(x->x.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Social connection not found"));if(!c.isEnabled())throw new IllegalArgumentException("Social connection is disabled");connections.markSynced(connectionId,tenant,OffsetDateTime.now());return connections.findById(c.getId()).orElseThrow();}}
